package com.example.finance;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class CategoryRepository {

    private final DataPaths dataPaths;
    private final List<Category> categories = new ArrayList<>();

    public CategoryRepository(DataPaths dataPaths) {
        this.dataPaths = dataPaths;
        load();
    }

    public List<Category> findAll() {
        return Collections.unmodifiableList(categories);
    }

    public void add(Category category) {
        categories.add(category);
        persist();
    }

    private void load() {
        for (String line : dataPaths.readLines(dataPaths.categoriesFile())) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            try {
                String[] parts = line.split("\\|", -1);
                String name = parts[0];
                BigDecimal monthlyTarget = new BigDecimal(parts[1]);
                categories.add(new Category(name, monthlyTarget));
            } catch (RuntimeException e) {
                System.err.println("Skipping malformed category line: " + line + " (" + e.getMessage() + ")");
            }
        }
    }

    private void persist() {
        List<String> lines = new ArrayList<>();
        lines.add("# name|monthlyTarget");
        for (Category category : categories) {
            lines.add(category.getName() + "|" + category.getMonthlyTarget());
        }
        dataPaths.writeLinesAtomic(dataPaths.categoriesFile(), lines);
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class TransactionRepository {

    private final DataPaths dataPaths;
    private final List<Transaction> transactions = new ArrayList<>();
    private long nextId = 1;

    public TransactionRepository(DataPaths dataPaths) {
        this.dataPaths = dataPaths;
        load();
    }

    public List<Transaction> findAll() {
        return Collections.unmodifiableList(transactions);
    }

    public Transaction add(LocalDate date, TransactionType type, String categoryName,
                            BigDecimal amount, String description) {
        Transaction transaction = new Transaction(nextId++, date, type, categoryName, amount, description);
        transactions.add(transaction);
        persist();
        return transaction;
    }

    private void load() {
        for (String line : dataPaths.readLines(dataPaths.transactionsFile())) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            try {
                String[] parts = line.split("\\|", -1);
                long id = Long.parseLong(parts[0]);
                LocalDate date = LocalDate.parse(parts[1]);
                TransactionType type = TransactionType.valueOf(parts[2]);
                String categoryName = parts[3];
                BigDecimal amount = new BigDecimal(parts[4]);
                String description = parts[5];
                transactions.add(new Transaction(id, date, type, categoryName, amount, description));
                if (id >= nextId) {
                    nextId = id + 1;
                }
            } catch (RuntimeException e) {
                System.err.println("Skipping malformed transaction line: " + line + " (" + e.getMessage() + ")");
            }
        }
    }

    private void persist() {
        List<String> lines = new ArrayList<>();
        lines.add("# id|date|type|categoryName|amount|description");
        for (Transaction transaction : transactions) {
            lines.add(transaction.getId() + "|" + transaction.getDate() + "|" + transaction.getType() + "|"
                    + transaction.getCategoryName() + "|" + transaction.getAmount() + "|" + transaction.getDescription());
        }
        dataPaths.writeLinesAtomic(dataPaths.transactionsFile(), lines);
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class RecurringObligationRepository {

    private final DataPaths dataPaths;
    private final List<RecurringObligation> obligations = new ArrayList<>();

    public RecurringObligationRepository(DataPaths dataPaths) {
        this.dataPaths = dataPaths;
        load();
    }

    public List<RecurringObligation> findAll() {
        return Collections.unmodifiableList(obligations);
    }

    public void add(RecurringObligation obligation) {
        obligations.add(obligation);
        persist();
    }

    private void load() {
        for (String line : dataPaths.readLines(dataPaths.recurringObligationsFile())) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            try {
                String[] parts = line.split("\\|", -1);
                String name = parts[0];
                String categoryName = parts[1];
                BigDecimal amount = new BigDecimal(parts[2]);
                int intervalMonths = Integer.parseInt(parts[3]);
                LocalDate startDate = LocalDate.parse(parts[4]);
                LocalDate endDate = parts[5].isEmpty() ? null : LocalDate.parse(parts[5]);
                String description = parts[6];
                obligations.add(new RecurringObligation(name, categoryName, amount, intervalMonths,
                        startDate, endDate, description));
            } catch (RuntimeException e) {
                System.err.println("Skipping malformed recurring obligation line: " + line + " (" + e.getMessage() + ")");
            }
        }
    }

    private void persist() {
        List<String> lines = new ArrayList<>();
        lines.add("# name|categoryName|amount|intervalMonths|startDate|endDate|description");
        for (RecurringObligation obligation : obligations) {
            lines.add(obligation.getName() + "|" + obligation.getCategoryName() + "|" + obligation.getAmount() + "|"
                    + obligation.getIntervalMonths() + "|" + obligation.getStartDate() + "|"
                    + obligation.getEndDate().map(LocalDate::toString).orElse("") + "|"
                    + obligation.getDescription().orElse(""));
        }
        dataPaths.writeLinesAtomic(dataPaths.recurringObligationsFile(), lines);
    }
}

