package com.example.finance;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/**
 * Goal progress, and allocating a month's leftover to a goal. Allocations
 * are gated against "leftover minus what's already been allocated this
 * month" so the same leftover can't be assigned twice.
 */
public class SavingsGoalService {

    private final SavingsGoalRepository savingsGoalRepository;
    private final GoalContributionRepository goalContributionRepository;
    private final BudgetService budgetService;
    private final CategoryRepository categoryRepository;

    public SavingsGoalService(SavingsGoalRepository savingsGoalRepository,
                               GoalContributionRepository goalContributionRepository,
                               BudgetService budgetService,
                               CategoryRepository categoryRepository) {
        this.savingsGoalRepository = savingsGoalRepository;
        this.goalContributionRepository = goalContributionRepository;
        this.budgetService = budgetService;
        this.categoryRepository = categoryRepository;
    }

    /**
     * Adds the goal, and — since a category has to exist before it can be
     * picked on the transaction/obligation forms — creates a matching
     * category (target 0) if one with this name doesn't already exist.
     */
    public void addGoal(SavingsGoal goal) {
        savingsGoalRepository.add(goal);
        boolean categoryExists = categoryRepository.findAll().stream()
                .anyMatch(c -> c.getName().equals(goal.getName()));
        if (!categoryExists) {
            categoryRepository.add(new Category(goal.getName(), BigDecimal.ZERO));
        }
    }

    public List<GoalProgress> goalProgress() {
        List<GoalProgress> progress = new ArrayList<>();
        for (SavingsGoal goal : savingsGoalRepository.findAll()) {
            progress.add(new GoalProgress(goal, totalSaved(goal.getName())));
        }
        return progress;
    }

    public BigDecimal totalSaved(String goalName) {
        return goalContributionRepository.findAll().stream()
                .filter(c -> c.getGoalName().equals(goalName))
                .map(GoalContribution::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    public BigDecimal totalContributions(YearMonth month) {
        return goalContributionRepository.findAll().stream()
                .filter(c -> YearMonth.from(c.getDate()).equals(month))
                .map(GoalContribution::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    public BigDecimal availableLeftover(YearMonth month) {
        return budgetService.leftover(month).subtract(totalContributions(month));
    }

    public void allocateLeftoverToGoal(String goalName, BigDecimal amount, YearMonth month) {
        if (amount == null || amount.signum() <= 0) {
            throw new IllegalArgumentException("Allocation amount must be positive.");
        }
        if (amount.compareTo(availableLeftover(month)) > 0) {
            throw new IllegalArgumentException("Allocation exceeds available leftover.");
        }
        goalContributionRepository.add(LocalDate.now(), goalName, amount);
    }

    public static class GoalProgress {
        private final SavingsGoal goal;
        private final BigDecimal savedAmount;

        public GoalProgress(SavingsGoal goal, BigDecimal savedAmount) {
            this.goal = goal;
            this.savedAmount = savedAmount;
        }

        public SavingsGoal getGoal() {
            return goal;
        }

        public BigDecimal getSavedAmount() {
            return savedAmount;
        }

        public double getPercentComplete() {
            BigDecimal target = goal.getTargetAmount();
            if (target.signum() <= 0) {
                return 0.0;
            }
            return savedAmount.divide(target, 4, RoundingMode.HALF_UP).doubleValue();
        }
    }
}

package com.example.finance;

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.control.TabPane;
import javafx.stage.Stage;

public class MainApp extends Application {

    @Override
    public void start(Stage stage) {
        DataPaths dataPaths = new DataPaths();
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        RecurringObligationService recurringObligationService = new RecurringObligationService(recurringObligationRepository);
        BudgetService budgetService = new BudgetService(categoryRepository, transactionRepository, recurringObligationService);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        GoalContributionRepository goalContributionRepository = new GoalContributionRepository(dataPaths);
        SavingsGoalService savingsGoalService = new SavingsGoalService(
                savingsGoalRepository, goalContributionRepository, budgetService, categoryRepository);
        CategoryService categoryService = new CategoryService(
                categoryRepository, transactionRepository, recurringObligationRepository, savingsGoalRepository);
        MonthSummaryService monthSummaryService = new MonthSummaryService(
                budgetService, savingsGoalService, recurringObligationService);

        MonthSummaryView monthSummaryView = new MonthSummaryView(monthSummaryService);
        TransactionEntryView transactionEntryView = new TransactionEntryView(
                categoryRepository, transactionRepository, categoryService);
        CategorySummaryView categorySummaryView = new CategorySummaryView(budgetService);
        SavingsGoalsView savingsGoalsView = new SavingsGoalsView(savingsGoalRepository, savingsGoalService);
        RecurringObligationsView recurringObligationsView = new RecurringObligationsView(
                categoryRepository, recurringObligationRepository, recurringObligationService);

        TabPane tabPane = new TabPane();
        tabPane.getTabs().addAll(
                monthSummaryView.asTab(),
                transactionEntryView.asTab(),
                categorySummaryView.asTab(),
                savingsGoalsView.asTab(),
                recurringObligationsView.asTab());

        // Entering any tab re-pulls the latest data, since transactions/goals/
        // obligations/categories entered in one tab feed the totals shown in the others.
        tabPane.getSelectionModel().selectedItemProperty().addListener((obs, oldTab, newTab) -> {
            transactionEntryView.refresh();
            categorySummaryView.refresh();
            savingsGoalsView.refresh();
            recurringObligationsView.refresh();
            monthSummaryView.refresh();
        });

        stage.setTitle("Personal Finance");
        stage.setScene(new Scene(tabPane, 1024, 720));
        stage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

