package com.example.finance;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/**
 * Goal progress, and allocating a month's leftover to a goal. Allocations
 * are gated against "leftover minus what's already been allocated this
 * month" so the same leftover can't be assigned twice.
 */
public class SavingsGoalService {

    private final SavingsGoalRepository savingsGoalRepository;
    private final GoalContributionRepository goalContributionRepository;
    private final BudgetService budgetService;
    private final CategoryRepository categoryRepository;
    private final CategoryService categoryService;

    public SavingsGoalService(SavingsGoalRepository savingsGoalRepository,
                               GoalContributionRepository goalContributionRepository,
                               BudgetService budgetService,
                               CategoryRepository categoryRepository,
                               CategoryService categoryService) {
        this.savingsGoalRepository = savingsGoalRepository;
        this.goalContributionRepository = goalContributionRepository;
        this.budgetService = budgetService;
        this.categoryRepository = categoryRepository;
        this.categoryService = categoryService;
    }

    /**
     * Adds the goal, and — since a category has to exist before it can be
     * picked on the transaction/obligation forms — creates a matching
     * category (target 0) if one with this name doesn't already exist.
     */
    public void addGoal(SavingsGoal goal) {
        savingsGoalRepository.add(goal);
        ensureCategoryExists(goal.getName());
    }

    /**
     * Updates a goal's target amount/date, and — if the name changed —
     * cascades the rename to its contribution history (so past progress
     * isn't silently orphaned) and to its matching category, if any.
     * Also backfills a matching category if this goal predates that
     * guarantee and never got one in the first place.
     */
    public void updateGoal(String originalName, SavingsGoal updated) {
        savingsGoalRepository.update(originalName, updated);
        if (!originalName.equals(updated.getName())) {
            goalContributionRepository.renameGoal(originalName, updated.getName());
            categoryRepository.findAll().stream()
                    .filter(c -> c.getName().equals(originalName))
                    .findFirst()
                    .ifPresent(existingCategory -> categoryService.update(
                            originalName, new Category(updated.getName(), existingCategory.getMonthlyTarget())));
        }
        ensureCategoryExists(updated.getName());
    }

    private void ensureCategoryExists(String name) {
        boolean categoryExists = categoryRepository.findAll().stream()
                .anyMatch(c -> c.getName().equals(name));
        if (!categoryExists) {
            categoryRepository.add(new Category(name, BigDecimal.ZERO));
        }
    }

    /**
     * Refuses to delete a goal that already has money saved toward it,
     * since that history would otherwise vanish silently.
     */
    public void deleteGoal(String name) {
        BigDecimal saved = totalSaved(name);
        if (saved.signum() > 0) {
            throw new IllegalStateException(
                    "Can't delete \"" + name + "\" — it already has " + saved + " saved. Rename it instead.");
        }
        savingsGoalRepository.remove(name);
    }

    public List<GoalProgress> goalProgress() {
        List<GoalProgress> progress = new ArrayList<>();
        for (SavingsGoal goal : savingsGoalRepository.findAll()) {
            progress.add(new GoalProgress(goal, totalSaved(goal.getName())));
        }
        return progress;
    }

    public BigDecimal totalSaved(String goalName) {
        return goalContributionRepository.findAll().stream()
                .filter(c -> c.getGoalName().equals(goalName))
                .map(GoalContribution::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    public BigDecimal totalContributions(YearMonth month) {
        return goalContributionRepository.findAll().stream()
                .filter(c -> YearMonth.from(c.getDate()).equals(month))
                .map(GoalContribution::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    public BigDecimal availableLeftover(YearMonth month) {
        return budgetService.leftover(month).subtract(totalContributions(month));
    }

    public void allocateLeftoverToGoal(String goalName, BigDecimal amount, YearMonth month) {
        if (amount == null || amount.signum() <= 0) {
            throw new IllegalArgumentException("Allocation amount must be positive.");
        }
        if (amount.compareTo(availableLeftover(month)) > 0) {
            throw new IllegalArgumentException("Allocation exceeds available leftover.");
        }
        goalContributionRepository.add(LocalDate.now(), goalName, amount);
    }

    public static class GoalProgress {
        private final SavingsGoal goal;
        private final BigDecimal savedAmount;

        public GoalProgress(SavingsGoal goal, BigDecimal savedAmount) {
            this.goal = goal;
            this.savedAmount = savedAmount;
        }

        public SavingsGoal getGoal() {
            return goal;
        }

        public BigDecimal getSavedAmount() {
            return savedAmount;
        }

        public double getPercentComplete() {
            BigDecimal target = goal.getTargetAmount();
            if (target.signum() <= 0) {
                return 0.0;
            }
            return savedAmount.divide(target, 4, RoundingMode.HALF_UP).doubleValue();
        }
    }
}

package com.example.finance;

import javafx.beans.property.SimpleObjectProperty;
import javafx.beans.property.SimpleStringProperty;
import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.geometry.Insets;
import javafx.scene.control.Button;
import javafx.scene.control.ComboBox;
import javafx.scene.control.DatePicker;
import javafx.scene.control.Label;
import javafx.scene.control.Separator;
import javafx.scene.control.Tab;
import javafx.scene.control.TableColumn;
import javafx.scene.control.TableView;
import javafx.scene.control.TextField;
import javafx.scene.layout.FlowPane;
import javafx.scene.layout.VBox;

import java.math.BigDecimal;
import java.time.YearMonth;

/**
 * Create/edit/delete savings goals and allocate the current month's leftover
 * to them, with a table of each goal's saved amount and progress.
 */
public class SavingsGoalsView {

    private final SavingsGoalRepository savingsGoalRepository;
    private final SavingsGoalService savingsGoalService;
    private final YearMonth month;

    private final ObservableList<SavingsGoal> goalOptions = FXCollections.observableArrayList();
    private final ObservableList<SavingsGoalService.GoalProgress> rows = FXCollections.observableArrayList();
    private final Label leftoverLabel = new Label();

    public SavingsGoalsView(SavingsGoalRepository savingsGoalRepository, SavingsGoalService savingsGoalService) {
        this(savingsGoalRepository, savingsGoalService, YearMonth.now());
    }

    public SavingsGoalsView(SavingsGoalRepository savingsGoalRepository, SavingsGoalService savingsGoalService,
                             YearMonth month) {
        this.savingsGoalRepository = savingsGoalRepository;
        this.savingsGoalService = savingsGoalService;
        this.month = month;
        leftoverLabel.setWrapText(true);
        refresh();
    }

    public Tab asTab() {
        Tab tab = new Tab("Savings Goals", buildContent());
        tab.setClosable(false);
        return tab;
    }

    public void refresh() {
        goalOptions.setAll(savingsGoalRepository.findAll());
        rows.setAll(savingsGoalService.goalProgress());
        leftoverLabel.setText("Available leftover this month: " + savingsGoalService.availableLeftover(month));
    }

    private VBox buildContent() {
        VBox root = new VBox(12, buildGoalManagement(), new Separator(), leftoverLabel, buildAllocationForm());
        root.setPadding(new Insets(12));
        return root;
    }

    private VBox buildGoalManagement() {
        TextField nameField = new TextField();
        nameField.setPromptText("Goal name");
        TextField targetField = new TextField();
        targetField.setPromptText("Target amount");
        DatePicker targetDatePicker = new DatePicker();
        targetDatePicker.setPromptText("Target date (optional)");
        Label status = new Label();
        status.setWrapText(true);

        TableView<SavingsGoalService.GoalProgress> table = buildGoalTable();

        Button saveButton = new Button("Add goal");
        Button deleteButton = new Button("Delete selected");
        deleteButton.setDisable(true);

        table.getSelectionModel().selectedItemProperty().addListener((obs, oldSelection, newSelection) -> {
            if (newSelection != null) {
                SavingsGoal goal = newSelection.getGoal();
                nameField.setText(goal.getName());
                targetField.setText(goal.getTargetAmount().toString());
                targetDatePicker.setValue(goal.getTargetDate().orElse(null));
                saveButton.setText("Update goal");
                deleteButton.setDisable(false);
            } else {
                saveButton.setText("Add goal");
                deleteButton.setDisable(true);
            }
        });

        saveButton.setOnAction(e -> {
            String name = nameField.getText().trim();
            if (name.isEmpty()) {
                status.setText("Goal name is required.");
                return;
            }
            try {
                BigDecimal target = new BigDecimal(targetField.getText().trim());
                SavingsGoalService.GoalProgress selected = table.getSelectionModel().getSelectedItem();
                SavingsGoal updated = new SavingsGoal(name, target, targetDatePicker.getValue());
                if (selected == null) {
                    savingsGoalService.addGoal(updated);
                    status.setText("Added goal \"" + name + "\" (and a matching category).");
                } else {
                    savingsGoalService.updateGoal(selected.getGoal().getName(), updated);
                    status.setText("Updated goal \"" + name + "\".");
                }
                table.getSelectionModel().clearSelection();
                nameField.clear();
                targetField.clear();
                targetDatePicker.setValue(null);
                refresh();
            } catch (NumberFormatException ex) {
                status.setText("Target amount must be a number.");
            }
        });

        deleteButton.setOnAction(e -> {
            SavingsGoalService.GoalProgress selected = table.getSelectionModel().getSelectedItem();
            if (selected == null) {
                return;
            }
            try {
                savingsGoalService.deleteGoal(selected.getGoal().getName());
                table.getSelectionModel().clearSelection();
                nameField.clear();
                targetField.clear();
                targetDatePicker.setValue(null);
                status.setText("Deleted goal \"" + selected.getGoal().getName() + "\".");
                refresh();
            } catch (IllegalStateException ex) {
                status.setText(ex.getMessage());
            }
        });

        FlowPane form = new FlowPane(8, 8, new Label("Goal:"), nameField, targetField, targetDatePicker,
                saveButton, deleteButton, status);
        VBox root = new VBox(6, form, table);
        TableSelectionUtil.clearSelectionOnClickOutside(root, table);
        return root;
    }

    private FlowPane buildAllocationForm() {
        ComboBox<SavingsGoal> goalBox = new ComboBox<>(goalOptions);
        TextField amountField = new TextField();
        amountField.setPromptText("Amount");
        Button allocateButton = new Button("Allocate to goal");
        Label status = new Label();
        status.setWrapText(true);

        allocateButton.setOnAction(e -> {
            SavingsGoal goal = goalBox.getValue();
            if (goal == null) {
                status.setText("Choose a goal.");
                return;
            }
            try {
                BigDecimal amount = new BigDecimal(amountField.getText().trim());
                savingsGoalService.allocateLeftoverToGoal(goal.getName(), amount, month);
                refresh();
                amountField.clear();
                status.setText("Allocated " + amount + " to \"" + goal.getName() + "\".");
            } catch (NumberFormatException ex) {
                status.setText("Amount must be a number.");
            } catch (IllegalArgumentException ex) {
                status.setText(ex.getMessage());
            }
        });

        return new FlowPane(8, 8, new Label("Allocate leftover:"), goalBox, amountField, allocateButton, status);
    }

    private TableView<SavingsGoalService.GoalProgress> buildGoalTable() {
        TableView<SavingsGoalService.GoalProgress> table = new TableView<>(rows);

        TableColumn<SavingsGoalService.GoalProgress, String> nameCol = new TableColumn<>("Goal");
        nameCol.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getGoal().getName()));

        TableColumn<SavingsGoalService.GoalProgress, BigDecimal> targetCol = new TableColumn<>("Target");
        targetCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getGoal().getTargetAmount()));

        TableColumn<SavingsGoalService.GoalProgress, BigDecimal> savedCol = new TableColumn<>("Saved");
        savedCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getSavedAmount()));

        TableColumn<SavingsGoalService.GoalProgress, String> percentCol = new TableColumn<>("Progress");
        percentCol.setCellValueFactory(cell -> new SimpleStringProperty(
                String.format("%.0f%%", cell.getValue().getPercentComplete() * 100)));

        table.getColumns().addAll(nameCol, targetCol, savedCol, percentCol);
        return table;
    }
}

